import { useMemo, useState } from 'react';
import { Link, useLocation, useParams } from 'wouter';
import { ArrowRight, CalendarDays, CheckCircle2, ClipboardList, Download, ExternalLink, IndianRupee, Plus, RefreshCw, Search, ShieldCheck, ShoppingCart, SlidersHorizontal, TrendingUp, X } from 'lucide-react';
import { useQueryClient } from '@tanstack/react-query';
import {
  ExportReportType,
  ListInventoryStatus,
  ListMedicinesStatus,
  SaleInputPaymentMethod,
  getGetDashboardSummaryQueryKey,
  getGetSaleInvoiceQueryKey,
  getGetReportSummaryQueryKey,
  getGetSalesChartQueryKey,
  getListCategoriesQueryKey,
  getListCustomersQueryKey,
  getListInventoryQueryKey,
  getListMedicinesQueryKey,
  getListPurchasesQueryKey,
  getListSalesQueryKey,
  getListSuppliersQueryKey,
  useCreateCustomer,
  useCreateMedicine,
  useCreatePurchase,
  useCreateSale,
  useCreateSupplier,
  useDeactivateMedicine,
  useExportReport,
  useGetDashboardSummary,
  useGetReportSummary,
  useGetSalesChart,
  useGetSaleInvoice,
  useListCategories,
  useListCustomers,
  useListInventory,
  useListMedicines,
  useListPurchases,
  useListSales,
  useListSuppliers,
  useLogin,
  useGetCurrentUser,
} from '@workspace/api-client-react';
import type { CustomerInput, MedicineInput, PurchaseInput, SaleInput, SupplierInput } from '@workspace/api-client-react';
import { AppShell, Currency, EmptyBlock, ErrorBlock, LoadingBlock, PageHeader } from '@/components/app-shell';

const money = (value: number | undefined | null) => <Currency value={value} />;
const date = (value: string | null | undefined) => value ? new Date(value).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }) : '—';
const statusLabel = (value: string) => value.replaceAll('_', ' ');

function MetricCard({ label, value, detail, tone = 'teal', icon: Icon }: { label: string; value: React.ReactNode; detail?: string; tone?: 'teal' | 'amber' | 'red' | 'blue'; icon: React.ElementType }) {
  return <div className="card-surface animate-in flex min-h-[142px] flex-col justify-between p-5"><div className="flex items-start justify-between"><span className="text-xs font-semibold uppercase tracking-[.08em] text-muted-foreground">{label}</span><span className={`rounded-lg p-2 ${tone === 'teal' ? 'bg-primary/10 text-primary' : tone === 'amber' ? 'bg-accent/15 text-[hsl(33,75%,35%)]' : tone === 'red' ? 'bg-destructive/10 text-destructive' : 'bg-blue-100 text-blue-700'}`}><Icon size={17} /></span></div><div><strong className="mt-3 block text-[25px] font-semibold tracking-[-.04em]">{value}</strong>{detail && <span className="mt-1 block text-xs text-muted-foreground">{detail}</span>}</div></div>;
}

function Dashboard() {
  const summary = useGetDashboardSummary({ query: { queryKey: getGetDashboardSummaryQueryKey(), retry: 1 } });
  const chart = useGetSalesChart({ days: 7 }, { query: { queryKey: getGetSalesChartQueryKey({ days: 7 }) } });
  const data = summary.data;
  return <AppShell><PageHeader eyebrow="Operations / Today" title="Good morning, stay ahead." description="A quiet view of what needs your attention across the pharmacy." action={<Link href="/pos" className="inline-flex items-center justify-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground shadow-sm hover:opacity-90" data-testid="link-open-pos"><Plus size={17} />Open point of sale</Link>} />
    {!data && summary.isLoading ? <LoadingBlock label="Loading your pharmacy snapshot" /> : summary.isError ? <ErrorBlock onRetry={() => summary.refetch()} /> : <div className="space-y-6">
      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <MetricCard label="Today's revenue" value={money(data?.todayRevenue)} detail={`${data?.transactionCount ?? 0} transactions`} icon={IndianRupee} />
        <MetricCard label="Monthly revenue" value={money(data?.monthlyRevenue)} detail="Current calendar month" tone="blue" icon={TrendingUp} />
        <MetricCard label="Inventory value" value={money(data?.inventoryValue)} detail="At purchase cost" tone="amber" icon={ShieldCheck} />
        <MetricCard label="Needs attention" value={(data?.lowStockCount ?? 0) + (data?.expiredCount ?? 0) + (data?.expiringCount ?? 0)} detail={`${data?.lowStockCount ?? 0} low stock · ${data?.expiredCount ?? 0} expired`} tone="red" icon={SlidersHorizontal} />
      </div>
      <div className="grid gap-6 xl:grid-cols-[1.45fr_1fr]">
        <section className="card-surface p-5 md:p-6"><div className="mb-6 flex items-start justify-between"><div><h2 className="font-semibold tracking-[-.02em]">Revenue rhythm</h2><p className="mt-1 text-xs text-muted-foreground">Last 7 days</p></div><Link href="/reports" className="text-xs font-semibold text-primary hover:underline" data-testid="link-dashboard-reports">View reports <ArrowRight size={13} className="ml-1 inline" /></Link></div>
          <div className="flex h-[190px] items-end gap-2 border-b border-l px-2 pb-0 pt-4">{(chart.data ?? []).map((point, index) => { const max = Math.max(...(chart.data ?? []).map((p) => p.revenue), 1); return <div key={point.date} className="group flex h-full flex-1 flex-col items-center justify-end gap-2"><div className="relative w-full rounded-t-md bg-primary/15 transition-all group-hover:bg-primary/35" style={{ height: `${Math.max(7, (point.revenue / max) * 100)}%` }}><div className="absolute inset-x-0 bottom-0 rounded-t-md bg-primary" style={{ height: `${Math.max(10, 30 + index * 7)}%` }} /></div><span className="text-[10px] text-muted-foreground">{new Date(point.date).toLocaleDateString('en-IN', { weekday: 'short' })}</span></div> })}</div>
          {!chart.data?.length && <div className="flex h-[190px] items-center justify-center text-xs text-muted-foreground">No chart activity for this period.</div>}
        </section>
        <section className="card-surface p-5 md:p-6"><div className="mb-5 flex items-start justify-between"><div><h2 className="font-semibold tracking-[-.02em]">Inventory watchlist</h2><p className="mt-1 text-xs text-muted-foreground">Low stock items from live inventory</p></div><Link href="/inventory" className="text-xs font-semibold text-primary hover:underline" data-testid="link-dashboard-inventory">Review <ArrowRight size={13} className="ml-1 inline" /></Link></div>{data?.lowStock?.length ? <div className="space-y-2">{data.lowStock.slice(0, 5).map((medicine) => <Link href="/inventory" key={medicine.id} className="flex items-center justify-between rounded-lg border border-transparent bg-muted/60 px-3 py-3 transition hover:border-primary/20 hover:bg-primary/5" data-testid={`row-watchlist-${medicine.id}`}><div className="min-w-0"><strong className="block truncate text-sm">{medicine.name}</strong><span className="text-xs text-muted-foreground">{medicine.categoryName} · reorder at {medicine.reorderLevel}</span></div><span className="mono ml-3 text-xs font-bold text-destructive">{medicine.stock} left</span></Link>)}</div> : <EmptyBlock label="No low-stock medicines right now." />}</section>
      </div>
      <div className="grid gap-6 xl:grid-cols-[1fr_1fr]">
        <section className="card-surface p-5 md:p-6"><div className="mb-5 flex items-center justify-between"><div><h2 className="font-semibold">Recent sales</h2><p className="mt-1 text-xs text-muted-foreground">Latest completed transactions</p></div><Link href="/sales" className="text-xs font-semibold text-primary" data-testid="link-dashboard-sales">All sales <ArrowRight size={13} className="ml-1 inline" /></Link></div>{data?.recentSales?.length ? <div className="divide-y">{data.recentSales.slice(0, 5).map((sale) => <Link href="/sales" className="flex items-center justify-between py-3 first:pt-0 last:pb-0" key={sale.id} data-testid={`row-recent-sale-${sale.id}`}><div><strong className="block text-sm">{sale.invoiceNumber}</strong><span className="text-xs text-muted-foreground">{sale.customer?.name ?? 'Walk-in customer'} · {date(sale.saleDate)}</span></div><span className="mono text-sm font-bold">{money(sale.total)}</span></Link>)}</div> : <EmptyBlock label="No completed sales yet." />}</section>
        <section className="card-surface p-5 md:p-6"><div className="mb-5"><h2 className="font-semibold">Top selling medicines</h2><p className="mt-1 text-xs text-muted-foreground">Based on current sales activity</p></div>{data?.topSelling?.length ? <div className="space-y-4">{data.topSelling.slice(0, 5).map((item, index) => <div className="flex items-center gap-3" key={item.medicineId}><span className="mono w-5 text-xs text-muted-foreground">0{index + 1}</span><div className="min-w-0 flex-1"><div className="mb-1 flex justify-between gap-2 text-sm"><span className="truncate font-medium">{item.medicineName}</span><span className="mono text-xs">{money(item.revenue)}</span></div><div className="h-1.5 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${Math.min(100, (item.quantity / Math.max(data.topSelling[0]?.quantity ?? 1, 1)) * 100)}%` }} /></div></div></div>)}</div> : <EmptyBlock label="Top sellers will appear after transactions." />}</section>
      </div>
    </div>}
  </AppShell>;
}

function Login() {
  const [, setLocation] = useLocation();
  const login = useLogin();
  const queryClient = useQueryClient();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const submit = (event: React.FormEvent) => { event.preventDefault(); login.mutate({ data: { email, password } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['/api/auth/me'] }); setLocation('/'); } }); };
  return <div className="fine-grid flex min-h-[100dvh] items-center justify-center bg-[#e8f0f1] p-4"><div className="grid w-full max-w-[930px] overflow-hidden rounded-2xl border bg-card shadow-[0_24px_80px_rgba(21,59,73,.12)] md:grid-cols-[.9fr_1.1fr]"><div className="hidden bg-sidebar p-10 text-sidebar-foreground md:block"><div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-sidebar-primary text-sidebar-primary-foreground"><ShieldCheck size={21} /></span><div><strong className="block text-lg text-white">Northstar</strong><span className="text-[10px] uppercase tracking-[.2em] text-sidebar-foreground/55">Pharmacy OS</span></div></div><div className="mt-28"><p className="mb-3 text-xs font-bold uppercase tracking-[.18em] text-sidebar-primary">Pharmacy operations</p><h1 className="max-w-xs text-4xl font-semibold leading-[1.08] tracking-[-.05em] text-white">Make the right call, every time.</h1><p className="mt-5 max-w-sm text-sm leading-6 text-sidebar-foreground/65">A focused command center for medicine safety, stock confidence, and a faster counter.</p></div><div className="mt-28 flex items-center gap-2 text-xs text-sidebar-foreground/50"><span className="h-2 w-2 rounded-full bg-sidebar-primary" />Protected workspace</div></div><div className="p-7 sm:p-12"><div className="mb-10 md:hidden"><div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-primary text-primary-foreground"><ShieldCheck size={21} /></span><strong className="text-lg">Northstar</strong></div></div><div className="mb-8"><p className="mb-2 text-xs font-bold uppercase tracking-[.18em] text-primary">Welcome back</p><h2 className="text-3xl font-semibold tracking-[-.04em]">Sign in to your pharmacy</h2><p className="mt-2 text-sm text-muted-foreground">Use your staff credentials to continue.</p></div><form onSubmit={submit} className="space-y-5"><label className="block text-sm font-medium">Work email<input value={email} onChange={(e) => setEmail(e.target.value)} type="email" required placeholder="name@pharmacy.com" className="mt-2 w-full rounded-lg border bg-background px-3.5 py-3 text-sm outline-none ring-primary/20 transition placeholder:text-muted-foreground/60 focus:ring-4" data-testid="input-email" /></label><label className="block text-sm font-medium">Password<input value={password} onChange={(e) => setPassword(e.target.value)} type="password" required placeholder="Enter your password" className="mt-2 w-full rounded-lg border bg-background px-3.5 py-3 text-sm outline-none ring-primary/20 transition placeholder:text-muted-foreground/60 focus:ring-4" data-testid="input-password" /></label>{login.isError && <p className="rounded-lg bg-destructive/10 px-3 py-2 text-xs text-destructive" data-testid="status-login-error">We could not verify those credentials. Please try again.</p>}<button type="submit" disabled={login.isPending} className="flex w-full items-center justify-center gap-2 rounded-lg bg-primary py-3 text-sm font-semibold text-primary-foreground transition hover:opacity-90 disabled:opacity-60" data-testid="button-submit-login">{login.isPending ? 'Signing in…' : 'Sign in securely'}<ArrowRight size={16} /></button></form><div className="mt-8 rounded-lg border border-primary/15 bg-primary/5 p-3 text-xs text-muted-foreground"><strong className="block text-foreground">Demo access</strong><span className="mt-1 block">admin@carepoint.test / admin123</span><span className="block">pharmacist@carepoint.test / pharma123</span><span className="block">staff@carepoint.test / staff123</span></div></div></div></div>;
}

function Medicines() {
  const queryClient = useQueryClient();
  const [search, setSearch] = useState('');
  const [status, setStatus] = useState<ListMedicinesStatus>('all');
  const [open, setOpen] = useState(false);
  const params = useMemo(() => ({ search: search || undefined, status, page: 1, pageSize: 50 }), [search, status]);
  const medicines = useListMedicines(params, { query: { queryKey: getListMedicinesQueryKey(params) } });
  const categories = useListCategories({ query: { queryKey: getListCategoriesQueryKey() } });
  const create = useCreateMedicine();
  const deactivate = useDeactivateMedicine();
  const [form, setForm] = useState<Partial<MedicineInput>>({ active: true, gstPercent: 0, prescriptionRequired: false, reorderLevel: 10, dosageForm: 'Tablet' });
  const submit = (event: React.FormEvent) => { event.preventDefault(); create.mutate({ data: { name: form.name ?? '', categoryId: Number(form.categoryId), dosageForm: form.dosageForm ?? 'Tablet', gstPercent: Number(form.gstPercent ?? 0), prescriptionRequired: Boolean(form.prescriptionRequired), reorderLevel: Number(form.reorderLevel ?? 0), active: true, genericName: form.genericName, brand: form.brand, manufacturer: form.manufacturer, strength: form.strength, barcode: form.barcode, description: form.description } }, { onSuccess: () => { setOpen(false); queryClient.invalidateQueries({ queryKey: getListMedicinesQueryKey(params) }); setForm({ active: true, gstPercent: 0, prescriptionRequired: false, reorderLevel: 10, dosageForm: 'Tablet' }); } }); };
  return <AppShell><PageHeader eyebrow="Catalog / Medicines" title="Medicine catalogue" description="Keep the catalogue accurate so every counter decision starts from clean information." action={<button onClick={() => setOpen(true)} className="inline-flex items-center justify-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground" data-testid="button-add-medicine"><Plus size={17} />Add medicine</button>} />
    <div className="mb-5 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search size={16} className="absolute left-3 top-3 text-muted-foreground" /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search name, generic name, barcode…" className="h-10 w-full rounded-lg border bg-card pl-9 pr-3 text-sm outline-none focus:ring-4 focus:ring-primary/10" data-testid="input-search-medicines" /></div><select value={status} onChange={(e) => setStatus(e.target.value as ListMedicinesStatus)} className="h-10 rounded-lg border bg-card px-3 text-sm capitalize outline-none" data-testid="select-medicine-status"><option value="all">All statuses</option><option value="active">Active</option><option value="inactive">Inactive</option><option value="low_stock">Low stock</option><option value="expired">Expired</option><option value="expiring">Expiring</option></select></div>
    {medicines.isLoading ? <LoadingBlock label="Loading medicine catalogue" /> : medicines.isError ? <ErrorBlock onRetry={() => medicines.refetch()} /> : <div className="card-surface overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[800px] text-left text-sm"><thead className="bg-muted/60 text-[10px] uppercase tracking-[.1em] text-muted-foreground"><tr><th className="px-5 py-3.5 font-bold">Medicine</th><th className="px-4 py-3.5 font-bold">Category</th><th className="px-4 py-3.5 font-bold">Form / strength</th><th className="px-4 py-3.5 font-bold">Stock</th><th className="px-4 py-3.5 font-bold">Nearest expiry</th><th className="px-5 py-3.5 text-right font-bold">Action</th></tr></thead><tbody className="divide-y">{medicines.data?.items?.map((medicine) => <tr key={medicine.id} className="transition hover:bg-muted/30" data-testid={`row-medicine-${medicine.id}`}><td className="px-5 py-4"><strong className="block">{medicine.name}</strong><span className="text-xs text-muted-foreground">{medicine.genericName || medicine.brand || 'No generic name'} {medicine.prescriptionRequired && <span className="ml-1 rounded bg-amber-100 px-1.5 py-0.5 text-[10px] font-bold text-amber-800">Rx</span>}</span></td><td className="px-4 py-4 text-muted-foreground">{medicine.categoryName}</td><td className="px-4 py-4 text-muted-foreground">{medicine.dosageForm}{medicine.strength ? ` · ${medicine.strength}` : ''}</td><td className="px-4 py-4"><span className={medicine.stock <= medicine.reorderLevel ? 'font-bold text-destructive' : 'font-medium'}>{medicine.stock}</span><span className="ml-1 text-xs text-muted-foreground">units</span></td><td className="px-4 py-4 text-muted-foreground">{date(medicine.nearestExpiry)}</td><td className="px-5 py-4 text-right"><button disabled={!medicine.active || deactivate.isPending} onClick={() => deactivate.mutate({ id: medicine.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListMedicinesQueryKey(params) }) })} className="rounded-md border px-2.5 py-1.5 text-xs font-semibold hover:bg-muted disabled:cursor-not-allowed disabled:opacity-40" data-testid={`button-deactivate-medicine-${medicine.id}`}>{medicine.active ? 'Deactivate' : 'Inactive'}</button></td></tr>)}</tbody></table></div>{!medicines.data?.items?.length && <EmptyBlock label="No medicines match this view." action={<button onClick={() => setOpen(true)} className="text-xs font-semibold text-primary" data-testid="button-empty-add-medicine">Add the first medicine</button>} />}</div>}
    {open && <Modal title="Add a medicine" onClose={() => setOpen(false)}><form onSubmit={submit} className="grid gap-4 sm:grid-cols-2"><Field label="Medicine name" value={form.name ?? ''} onChange={(value) => setForm({ ...form, name: value })} required /><Field label="Generic name" value={form.genericName ?? ''} onChange={(value) => setForm({ ...form, genericName: value })} /><Field label="Brand" value={form.brand ?? ''} onChange={(value) => setForm({ ...form, brand: value })} /><Field label="Manufacturer" value={form.manufacturer ?? ''} onChange={(value) => setForm({ ...form, manufacturer: value })} /><label className="block text-sm font-medium">Category<select required value={form.categoryId ?? ''} onChange={(e) => setForm({ ...form, categoryId: Number(e.target.value) })} className="mt-1.5 h-10 w-full rounded-lg border bg-background px-3 text-sm" data-testid="select-medicine-category"><option value="">Select category</option>{categories.data?.map((category) => <option value={category.id} key={category.id}>{category.name}</option>)}</select></label><Field label="Dosage form" value={form.dosageForm ?? ''} onChange={(value) => setForm({ ...form, dosageForm: value })} required /><Field label="Strength" value={form.strength ?? ''} onChange={(value) => setForm({ ...form, strength: value })} /><Field label="Reorder level" type="number" value={String(form.reorderLevel ?? '')} onChange={(value) => setForm({ ...form, reorderLevel: Number(value) })} /><div className="col-span-full flex items-center gap-2"><input type="checkbox" checked={Boolean(form.prescriptionRequired)} onChange={(e) => setForm({ ...form, prescriptionRequired: e.target.checked })} id="prescription" data-testid="checkbox-prescription" /><label htmlFor="prescription" className="text-sm">Prescription required</label></div><div className="col-span-full flex justify-end gap-2 border-t pt-4"><button type="button" onClick={() => setOpen(false)} className="rounded-lg border px-4 py-2 text-sm font-semibold" data-testid="button-cancel-medicine">Cancel</button><button disabled={create.isPending} className="rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground disabled:opacity-60" data-testid="button-save-medicine">{create.isPending ? 'Saving…' : 'Save medicine'}</button></div></form></Modal>}
  </AppShell>;
}

function Field({ label, value, onChange, required, type = 'text' }: { label: string; value: string; onChange: (value: string) => void; required?: boolean; type?: string }) { return <label className="block text-sm font-medium">{label}<input required={required} type={type} value={value} onChange={(e) => onChange(e.target.value)} className="mt-1.5 h-10 w-full rounded-lg border bg-background px-3 text-sm outline-none focus:ring-4 focus:ring-primary/10" data-testid={`input-${label.toLowerCase().replaceAll(' ', '-')}`} /></label>; }

function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: React.ReactNode }) { return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/40 p-4"><div className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-xl border bg-card shadow-2xl"><div className="flex items-center justify-between border-b px-6 py-4"><h2 className="font-semibold">{title}</h2><button onClick={onClose} className="rounded-md p-1.5 text-muted-foreground hover:bg-muted" aria-label="Close dialog" data-testid="button-close-dialog"><X size={18} /></button></div><div className="p-6">{children}</div></div></div>; }

function Inventory() {
  const [search, setSearch] = useState('');
  const [status, setStatus] = useState<ListInventoryStatus>('all');
  const params = useMemo(() => ({ search: search || undefined, status, page: 1, pageSize: 50 }), [search, status]);
  const inventory = useListInventory(params, { query: { queryKey: getListInventoryQueryKey(params) } });
  return <AppShell><PageHeader eyebrow="Operations / Control" title="Inventory control" description="Batch-level visibility for expiry, shelf health, and replenishment." action={<button onClick={() => inventory.refetch()} className="inline-flex items-center justify-center gap-2 rounded-lg border bg-card px-4 py-2.5 text-sm font-semibold hover:bg-muted" data-testid="button-refresh-inventory"><RefreshCw size={16} />Refresh</button>} /><div className="mb-5 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search size={16} className="absolute left-3 top-3 text-muted-foreground" /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search inventory…" className="h-10 w-full rounded-lg border bg-card pl-9 text-sm outline-none focus:ring-4 focus:ring-primary/10" data-testid="input-search-inventory" /></div><select value={status} onChange={(e) => setStatus(e.target.value as ListInventoryStatus)} className="h-10 rounded-lg border bg-card px-3 text-sm capitalize" data-testid="select-inventory-status"><option value="all">All inventory</option><option value="healthy">Healthy</option><option value="low_stock">Low stock</option><option value="expiring">Expiring</option><option value="expired">Expired</option></select></div>{inventory.isLoading ? <LoadingBlock label="Checking batch health" /> : inventory.isError ? <ErrorBlock onRetry={() => inventory.refetch()} /> : <div className="card-surface overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[940px] text-left text-sm"><thead className="bg-muted/60 text-[10px] uppercase tracking-[.1em] text-muted-foreground"><tr><th className="px-5 py-3.5">Medicine</th><th className="px-4 py-3.5">Status</th><th className="px-4 py-3.5">Total units</th><th className="px-4 py-3.5">Batches</th><th className="px-4 py-3.5">Nearest expiry</th><th className="px-4 py-3.5">Supplier</th></tr></thead><tbody className="divide-y">{inventory.data?.items?.map((item) => <tr key={item.medicine.id} className="hover:bg-muted/30" data-testid={`row-inventory-${item.medicine.id}`}><td className="px-5 py-4"><strong>{item.medicine.name}</strong><span className="ml-2 text-xs text-muted-foreground">{item.medicine.strength}</span></td><td className="px-4 py-4"><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold capitalize ${item.status === 'healthy' ? 'bg-emerald-100 text-emerald-800' : item.status === 'low_stock' ? 'bg-amber-100 text-amber-800' : 'bg-red-100 text-red-800'}`}>{statusLabel(item.status)}</span></td><td className="px-4 py-4 mono">{item.medicine.stock}</td><td className="px-4 py-4 text-muted-foreground">{item.batches.length} batch{item.batches.length === 1 ? '' : 'es'}</td><td className="px-4 py-4"><span className={item.daysUntilExpiry !== null && item.daysUntilExpiry < 30 ? 'font-semibold text-destructive' : ''}>{item.daysUntilExpiry !== null ? `${item.daysUntilExpiry} days · ${date(item.medicine.nearestExpiry)}` : 'No expiry recorded'}</span></td><td className="px-4 py-4 text-muted-foreground">{item.batches[0]?.supplierName ?? '—'}</td></tr>)}</tbody></table></div>{!inventory.data?.items?.length && <EmptyBlock label="No inventory items match this filter." />}</div>}</AppShell>;
}

function SimpleListPage({ kind }: { kind: 'purchases' | 'suppliers' | 'customers' | 'sales' }) {
  const [search, setSearch] = useState('');
  const [open, setOpen] = useState(false);
  const [location, setLocation] = useLocation();
  const query = useMemo(() => ({ search: search || undefined, page: 1, pageSize: 50 }), [search]);
  const suppliers = useListSuppliers({ search: search || undefined });
  const customers = useListCustomers(query, { query: { queryKey: getListCustomersQueryKey(query) } });
  const purchases = useListPurchases(query, { query: { queryKey: getListPurchasesQueryKey(query) } });
  const sales = useListSales(query, { query: { queryKey: getListSalesQueryKey(query) } });
  const createSupplier = useCreateSupplier();
  const createCustomer = useCreateCustomer();
  const [form, setForm] = useState<Record<string, string>>({});
  const config = { purchases: { eyebrow: 'Procurement / Ledger', title: 'Purchases', description: 'Record incoming stock and keep supplier invoices traceable.', action: 'New purchase' }, suppliers: { eyebrow: 'Procurement / Partners', title: 'Suppliers', description: 'Know who keeps your shelves moving.', action: 'Add supplier' }, customers: { eyebrow: 'Relationships / Customers', title: 'Customers', description: 'A clear, respectful view of customer purchase context.', action: 'Add customer' }, sales: { eyebrow: 'Checkout / History', title: 'Sales & invoices', description: 'Completed transactions, searchable when a customer needs you.', action: 'Open point of sale' } }[kind];
  const loading = kind === 'purchases' ? purchases.isLoading : kind === 'suppliers' ? suppliers.isLoading : kind === 'customers' ? customers.isLoading : sales.isLoading;
  const error = kind === 'purchases' ? purchases.isError : kind === 'suppliers' ? suppliers.isError : kind === 'customers' ? customers.isError : sales.isError;
  const refresh = kind === 'purchases' ? purchases.refetch : kind === 'suppliers' ? suppliers.refetch : kind === 'customers' ? customers.refetch : sales.refetch;
  const submit = (event: React.FormEvent) => { event.preventDefault(); if (kind === 'suppliers') createSupplier.mutate({ data: { companyName: form.companyName ?? '', contactPerson: form.contactPerson ?? '', phone: form.phone ?? '', email: form.email || null, address: form.address ?? '', gstNumber: form.gstNumber } as SupplierInput }, { onSuccess: () => { setOpen(false); refresh(); } }); if (kind === 'customers') createCustomer.mutate({ data: { name: form.name ?? '', phone: form.phone ?? '', email: form.email || null, address: form.address ?? '' } as CustomerInput }, { onSuccess: () => { setOpen(false); refresh(); } }); };
  if (kind === 'sales') return <SalesContent sales={sales} search={search} setSearch={setSearch} setLocation={setLocation} />;
  return <AppShell><PageHeader eyebrow={config.eyebrow} title={config.title} description={config.description} action={<button onClick={() => kind === 'purchases' ? setLocation('/purchases/new') : setOpen(true)} className="inline-flex items-center justify-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground" data-testid={`button-add-${kind}`}>{kind === 'purchases' ? <ClipboardAction /> : <Plus size={17} />}{config.action}</button>} /><div className="mb-5 flex gap-3"><div className="relative max-w-xl flex-1"><Search size={16} className="absolute left-3 top-3 text-muted-foreground" /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder={`Search ${kind}…`} className="h-10 w-full rounded-lg border bg-card pl-9 text-sm outline-none focus:ring-4 focus:ring-primary/10" data-testid={`input-search-${kind}`} /></div><button onClick={() => refresh()} className="rounded-lg border bg-card px-3 text-muted-foreground hover:bg-muted" data-testid={`button-refresh-${kind}`}><RefreshCw size={16} /></button></div>{loading ? <LoadingBlock label={`Loading ${kind}`} /> : error ? <ErrorBlock onRetry={() => refresh()} /> : kind === 'suppliers' ? <SupplierTable items={suppliers.data ?? []} /> : kind === 'customers' ? <CustomerTable items={customers.data?.items ?? []} /> : <PurchaseTable items={purchases.data?.items ?? []} />}{open && kind !== 'purchases' && <Modal title={kind === 'suppliers' ? 'Add supplier' : 'Add customer'} onClose={() => setOpen(false)}><form onSubmit={submit} className="grid gap-4 sm:grid-cols-2">{kind === 'suppliers' ? <><Field label="Company name" required value={form.companyName ?? ''} onChange={(v) => setForm({ ...form, companyName: v })} /><Field label="Contact person" required value={form.contactPerson ?? ''} onChange={(v) => setForm({ ...form, contactPerson: v })} /><Field label="Phone" required value={form.phone ?? ''} onChange={(v) => setForm({ ...form, phone: v })} /><Field label="Email" value={form.email ?? ''} onChange={(v) => setForm({ ...form, email: v })} /><Field label="Address" required value={form.address ?? ''} onChange={(v) => setForm({ ...form, address: v })} /><Field label="GST number" value={form.gstNumber ?? ''} onChange={(v) => setForm({ ...form, gstNumber: v })} /></> : <><Field label="Name" required value={form.name ?? ''} onChange={(v) => setForm({ ...form, name: v })} /><Field label="Phone" required value={form.phone ?? ''} onChange={(v) => setForm({ ...form, phone: v })} /><Field label="Email" value={form.email ?? ''} onChange={(v) => setForm({ ...form, email: v })} /><Field label="Address" required value={form.address ?? ''} onChange={(v) => setForm({ ...form, address: v })} /></>}<div className="col-span-full flex justify-end gap-2 border-t pt-4"><button type="button" onClick={() => setOpen(false)} className="rounded-lg border px-4 py-2 text-sm font-semibold" data-testid="button-cancel-record">Cancel</button><button className="rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground" data-testid="button-save-record">Save record</button></div></form></Modal>}</AppShell>;
}

function ClipboardAction() { return <ClipboardList size={17} />; }

function SupplierTable({ items }: { items: any[] }) { return <div className="card-surface overflow-hidden">{items.length ? <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm"><thead className="bg-muted/60 text-[10px] uppercase tracking-[.1em] text-muted-foreground"><tr><th className="px-5 py-3.5">Company</th><th className="px-4 py-3.5">Contact</th><th className="px-4 py-3.5">Phone</th><th className="px-4 py-3.5">Purchases</th><th className="px-5 py-3.5 text-right">Total purchased</th></tr></thead><tbody className="divide-y">{items.map((item) => <tr key={item.id} className="hover:bg-muted/30" data-testid={`row-supplier-${item.id}`}><td className="px-5 py-4"><strong>{item.companyName}</strong><span className="block text-xs text-muted-foreground">{item.gstNumber || 'GST not recorded'}</span></td><td className="px-4 py-4">{item.contactPerson}</td><td className="px-4 py-4 text-muted-foreground">{item.phone}</td><td className="px-4 py-4 mono">{item.purchaseCount}</td><td className="px-5 py-4 text-right font-semibold">{money(item.totalPurchased)}</td></tr>)}</tbody></table></div> : <EmptyBlock label="No supplier records yet." />}</div>; }
function CustomerTable({ items }: { items: any[] }) { return <div className="card-surface overflow-hidden">{items.length ? <div className="overflow-x-auto"><table className="w-full min-w-[700px] text-left text-sm"><thead className="bg-muted/60 text-[10px] uppercase tracking-[.1em] text-muted-foreground"><tr><th className="px-5 py-3.5">Customer</th><th className="px-4 py-3.5">Contact</th><th className="px-4 py-3.5">Purchases</th><th className="px-4 py-3.5">Last purchase</th><th className="px-5 py-3.5 text-right">Lifetime value</th></tr></thead><tbody className="divide-y">{items.map((item) => <tr key={item.id} className="hover:bg-muted/30" data-testid={`row-customer-${item.id}`}><td className="px-5 py-4"><strong>{item.name}</strong><span className="block text-xs text-muted-foreground">{item.email || 'No email recorded'}</span></td><td className="px-4 py-4">{item.phone}</td><td className="px-4 py-4 mono">{item.purchaseCount}</td><td className="px-4 py-4 text-muted-foreground">{date(item.lastPurchaseDate)}</td><td className="px-5 py-4 text-right font-semibold">{money(item.totalSpent)}</td></tr>)}</tbody></table></div> : <EmptyBlock label="No customer records yet." />}</div>; }
function PurchaseTable({ items }: { items: any[] }) { return <div className="card-surface overflow-hidden">{items.length ? <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm"><thead className="bg-muted/60 text-[10px] uppercase tracking-[.1em] text-muted-foreground"><tr><th className="px-5 py-3.5">Invoice</th><th className="px-4 py-3.5">Supplier</th><th className="px-4 py-3.5">Purchase date</th><th className="px-4 py-3.5">Items</th><th className="px-5 py-3.5 text-right">Total</th></tr></thead><tbody className="divide-y">{items.map((item) => <tr key={item.id} className="hover:bg-muted/30" data-testid={`row-purchase-${item.id}`}><td className="px-5 py-4 mono font-semibold">{item.invoiceNumber}</td><td className="px-4 py-4">{item.supplier.companyName}</td><td className="px-4 py-4 text-muted-foreground">{date(item.purchaseDate)}</td><td className="px-4 py-4 text-muted-foreground">{item.items.length}</td><td className="px-5 py-4 text-right font-semibold">{money(item.total)}</td></tr>)}</tbody></table></div> : <EmptyBlock label="No purchases recorded yet." />}</div>; }

function SalesContent({ sales, search, setSearch, setLocation }: { sales: any; search: string; setSearch: (v: string) => void; setLocation: (v: string) => void }) { return <AppShell><PageHeader eyebrow="Checkout / History" title="Sales & invoices" description="Completed transactions, searchable when a customer needs you." action={<Link href="/pos" className="inline-flex items-center justify-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground" data-testid="link-sales-pos"><Plus size={17} />Open point of sale</Link>} /><div className="mb-5 flex gap-3"><div className="relative max-w-xl flex-1"><Search size={16} className="absolute left-3 top-3 text-muted-foreground" /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search invoice or customer…" className="h-10 w-full rounded-lg border bg-card pl-9 text-sm outline-none focus:ring-4 focus:ring-primary/10" data-testid="input-search-sales" /></div></div>{sales.isLoading ? <LoadingBlock label="Loading completed sales" /> : sales.isError ? <ErrorBlock onRetry={() => sales.refetch()} /> : <div className="card-surface overflow-hidden">{sales.data?.items?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[800px] text-left text-sm"><thead className="bg-muted/60 text-[10px] uppercase tracking-[.1em] text-muted-foreground"><tr><th className="px-5 py-3.5">Invoice</th><th className="px-4 py-3.5">Customer</th><th className="px-4 py-3.5">Date</th><th className="px-4 py-3.5">Payment</th><th className="px-5 py-3.5 text-right">Total</th></tr></thead><tbody className="divide-y">{sales.data.items.map((item: any) => <tr key={item.id} className="cursor-pointer hover:bg-muted/30" onClick={() => setLocation(`/sales/${item.id}`)} data-testid={`row-sale-${item.id}`}><td className="px-5 py-4 mono font-semibold text-primary">{item.invoiceNumber}</td><td className="px-4 py-4">{item.customer?.name ?? 'Walk-in customer'}</td><td className="px-4 py-4 text-muted-foreground">{date(item.saleDate)}</td><td className="px-4 py-4"><span className="rounded-full bg-muted px-2.5 py-1 text-[11px] font-semibold">{item.paymentMethod}</span></td><td className="px-5 py-4 text-right font-semibold">{money(item.total)}</td></tr>)}</tbody></table></div> : <EmptyBlock label="No sales match this search." />}</div>}</AppShell>; }

function SaleDetails() {
  const params = useParams<{ id: string }>();
  const id = Number(params.id);
  const invoice = useGetSaleInvoice(id, { query: { queryKey: getGetSaleInvoiceQueryKey(id) } });
  const sale = invoice.data?.sale;
  return <AppShell><PageHeader eyebrow="Checkout / Invoice" title={sale?.invoiceNumber ?? 'Invoice'} description={sale ? `${sale.customer?.name ?? 'Walk-in customer'} · ${date(sale.saleDate)}` : 'Loading invoice details'} action={<Link href="/sales" className="rounded-lg border bg-card px-4 py-2.5 text-sm font-semibold hover:bg-muted" data-testid="link-back-sales">Back to sales</Link>} />{invoice.isLoading ? <LoadingBlock label="Preparing invoice" /> : invoice.isError || !sale ? <ErrorBlock onRetry={() => invoice.refetch()} label="This invoice could not be loaded." /> : <div className="grid gap-5 lg:grid-cols-[1fr_300px]"><section className="card-surface overflow-hidden"><div className="border-b bg-muted/30 px-6 py-5"><div className="flex items-center gap-2 text-xs text-emerald-700"><CheckCircle2 size={15} />Payment recorded · {sale.paymentMethod}</div></div><div className="overflow-x-auto"><table className="w-full min-w-[560px] text-left text-sm"><thead className="text-[10px] uppercase tracking-[.1em] text-muted-foreground"><tr><th className="px-6 py-3.5">Medicine</th><th className="px-4 py-3.5">Batch</th><th className="px-4 py-3.5">Qty</th><th className="px-6 py-3.5 text-right">Amount</th></tr></thead><tbody className="divide-y">{sale.items.map((item) => <tr key={item.id} data-testid={`row-invoice-item-${item.id}`}><td className="px-6 py-4 font-medium">{item.medicineName}</td><td className="px-4 py-4 mono text-xs text-muted-foreground">{item.batchNumber}</td><td className="px-4 py-4 mono">{item.quantity}</td><td className="px-6 py-4 text-right font-semibold">{money(item.lineTotal)}</td></tr>)}</tbody></table></div></section><aside className="card-surface p-5"><h2 className="mb-5 font-semibold">Invoice summary</h2><div className="space-y-3 text-sm"><div className="flex justify-between"><span className="text-muted-foreground">Subtotal</span><span>{money(sale.subtotal)}</span></div><div className="flex justify-between"><span className="text-muted-foreground">Discount</span><span>{money(sale.discountAmount)}</span></div><div className="flex justify-between"><span className="text-muted-foreground">GST</span><span>{money(sale.gstTotal)}</span></div><div className="flex justify-between border-t pt-3 text-base font-bold"><span>Total</span><span className="mono">{money(sale.total)}</span></div></div><button onClick={() => window.print()} className="mt-6 flex w-full items-center justify-center gap-2 rounded-lg border py-2.5 text-sm font-semibold hover:bg-muted" data-testid="button-print-invoice"><ExternalLink size={15} />Print invoice</button></aside></div>}</AppShell>;
}

function POS() {
  const medicines = useListMedicines({ status: 'active', page: 1, pageSize: 100 }, { query: { queryKey: getListMedicinesQueryKey({ status: 'active', page: 1, pageSize: 100 }) } });
  const customers = useListCustomers({ page: 1, pageSize: 100 }, { query: { queryKey: getListCustomersQueryKey({ page: 1, pageSize: 100 }) } });
  const sale = useCreateSale();
  const queryClient = useQueryClient();
  const [search, setSearch] = useState('');
  const [cart, setCart] = useState<{ medicineId: number; name: string; price: number; quantity: number }[]>([]);
  const [customerId, setCustomerId] = useState<number | null>(null);
  const [payment, setPayment] = useState<SaleInputPaymentMethod>('CASH');
  const filtered = (medicines.data?.items ?? []).filter((item) => item.name.toLowerCase().includes(search.toLowerCase()) || item.genericName?.toLowerCase().includes(search.toLowerCase()));
  const subtotal = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const add = (medicine: any) => setCart((current) => current.some((item) => item.medicineId === medicine.id) ? current.map((item) => item.medicineId === medicine.id ? { ...item, quantity: item.quantity + 1 } : item) : [...current, { medicineId: medicine.id, name: medicine.name, price: medicine.inventoryValue && medicine.stock ? medicine.inventoryValue / medicine.stock : 0, quantity: 1 }]);
  const submit = () => { const data: SaleInput = { customerId, paymentMethod: payment, discountAmount: 0, items: cart.map((item) => ({ medicineId: item.medicineId, quantity: item.quantity, discountPercent: 0 })) }; sale.mutate({ data }, { onSuccess: () => { setCart([]); queryClient.invalidateQueries({ queryKey: getListSalesQueryKey({ page: 1, pageSize: 50 }) }); } }); };
  return <AppShell><PageHeader eyebrow="Checkout / Counter" title="Point of sale" description="A focused checkout flow for fast, safe customer service." action={<span className="flex items-center gap-2 text-xs text-muted-foreground"><span className="h-2 w-2 rounded-full bg-emerald-500" />Ready for checkout</span>} /><div className="grid gap-5 xl:grid-cols-[1fr_390px]"><section className="card-surface p-5"><div className="mb-5 flex items-center justify-between"><div><h2 className="font-semibold">Find a medicine</h2><p className="mt-1 text-xs text-muted-foreground">Select an item to add it to the current sale.</p></div><span className="mono rounded-full bg-muted px-2.5 py-1 text-[11px]">{medicines.data?.total ?? 0} active</span></div><div className="relative mb-4"><Search size={16} className="absolute left-3 top-3 text-muted-foreground" /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search medicine…" className="h-10 w-full rounded-lg border bg-background pl-9 text-sm outline-none focus:ring-4 focus:ring-primary/10" data-testid="input-pos-search" /></div>{medicines.isLoading ? <LoadingBlock label="Loading medicines" /> : <div className="grid gap-2 sm:grid-cols-2">{filtered.slice(0, 12).map((medicine) => <button key={medicine.id} onClick={() => add(medicine)} className="flex items-center justify-between rounded-lg border p-3 text-left transition hover:border-primary/40 hover:bg-primary/5" data-testid={`button-add-pos-${medicine.id}`}><span className="min-w-0"><strong className="block truncate text-sm">{medicine.name}</strong><span className="block truncate text-xs text-muted-foreground">{medicine.dosageForm} {medicine.strength} · {medicine.stock} in stock</span></span><Plus size={16} className="ml-2 shrink-0 text-primary" /></button>)}</div>}</section><aside className="card-surface flex flex-col p-5"><div className="mb-5 flex items-center justify-between"><div><h2 className="font-semibold">Current sale</h2><p className="mt-1 text-xs text-muted-foreground">{cart.length} line items</p></div><button onClick={() => setCart([])} className="text-xs font-semibold text-muted-foreground hover:text-destructive" data-testid="button-clear-cart">Clear</button></div><div className="flex-1">{cart.length ? <div className="space-y-3">{cart.map((item) => <div className="flex items-center gap-3" key={item.medicineId}><div className="min-w-0 flex-1"><strong className="block truncate text-sm">{item.name}</strong><span className="text-xs text-muted-foreground">{money(item.price)} each</span></div><div className="flex items-center gap-2"><button onClick={() => setCart(cart.map((line) => line.medicineId === item.medicineId ? { ...line, quantity: Math.max(1, line.quantity - 1) } : line))} className="h-6 w-6 rounded border text-sm" data-testid={`button-decrease-${item.medicineId}`}>−</button><span className="mono w-4 text-center text-xs">{item.quantity}</span><button onClick={() => setCart(cart.map((line) => line.medicineId === item.medicineId ? { ...line, quantity: line.quantity + 1 } : line))} className="h-6 w-6 rounded border text-sm" data-testid={`button-increase-${item.medicineId}`}>+</button></div><span className="mono w-20 text-right text-xs font-bold">{money(item.price * item.quantity)}</span></div>)}</div> : <div className="flex h-48 flex-col items-center justify-center text-center"><ShoppingCartIcon /><p className="mt-3 text-sm font-medium">Your sale is empty</p><p className="mt-1 text-xs text-muted-foreground">Add a medicine to begin.</p></div>}</div><div className="mt-5 border-t pt-4"><label className="mb-3 block text-xs font-semibold text-muted-foreground">Customer (optional)<select value={customerId ?? ''} onChange={(e) => setCustomerId(e.target.value ? Number(e.target.value) : null)} className="mt-1.5 h-9 w-full rounded-lg border bg-background px-2 text-sm" data-testid="select-pos-customer"><option value="">Walk-in customer</option>{customers.data?.items?.map((customer) => <option value={customer.id} key={customer.id}>{customer.name} · {customer.phone}</option>)}</select></label><div className="mb-4 flex items-center justify-between"><span className="text-sm text-muted-foreground">Subtotal</span><strong className="mono text-lg">{money(subtotal)}</strong></div><select value={payment} onChange={(e) => setPayment(e.target.value as SaleInputPaymentMethod)} className="mb-3 h-10 w-full rounded-lg border bg-background px-3 text-sm" data-testid="select-payment-method"><option value="CASH">Cash</option><option value="UPI">UPI</option><option value="CARD">Card</option></select><button disabled={!cart.length || sale.isPending} onClick={submit} className="w-full rounded-lg bg-primary py-3 text-sm font-semibold text-primary-foreground disabled:cursor-not-allowed disabled:opacity-50" data-testid="button-complete-sale">{sale.isPending ? 'Completing sale…' : 'Complete sale'}</button>{sale.isError && <p className="mt-2 text-xs text-destructive">Sale could not be completed. Check stock and try again.</p>}</div></aside></div></AppShell>;
}
function ShoppingCartIcon() { return <ShoppingCart size={25} className="text-muted-foreground/40" />; }

function PurchaseEntry() {
  const [, setLocation] = useLocation();
  const suppliers = useListSuppliers();
  const medicines = useListMedicines({ status: 'active', page: 1, pageSize: 100 }, { query: { queryKey: getListMedicinesQueryKey({ status: 'active', page: 1, pageSize: 100 }) } });
  const create = useCreatePurchase();
  const [form, setForm] = useState({ supplierId: '', invoiceNumber: '', purchaseDate: new Date().toISOString().slice(0, 10), medicineId: '', batchNumber: '', manufacturingDate: '', expiryDate: '', quantity: '1', purchasePrice: '', sellingPrice: '', mrp: '', gstPercent: '0' });
  const submit = (event: React.FormEvent) => { event.preventDefault(); create.mutate({ data: { supplierId: Number(form.supplierId), invoiceNumber: form.invoiceNumber, purchaseDate: form.purchaseDate, items: [{ medicineId: Number(form.medicineId), batchNumber: form.batchNumber, manufacturingDate: form.manufacturingDate, expiryDate: form.expiryDate, quantity: Number(form.quantity), purchasePrice: Number(form.purchasePrice), sellingPrice: Number(form.sellingPrice), mrp: Number(form.mrp), gstPercent: Number(form.gstPercent) }] } }, { onSuccess: () => setLocation('/purchases') }); };
  return <AppShell><PageHeader eyebrow="Procurement / Intake" title="Record a purchase" description="Add one supplier invoice and its first batch to inventory. You can continue building the ledger from here." action={<button onClick={() => setLocation('/purchases')} className="rounded-lg border bg-card px-4 py-2.5 text-sm font-semibold hover:bg-muted" data-testid="button-cancel-purchase">Cancel</button>} /><form onSubmit={submit} className="card-surface grid gap-5 p-6"><div className="grid gap-4 md:grid-cols-3"><label className="block text-sm font-medium">Supplier<select required value={form.supplierId} onChange={(e) => setForm({ ...form, supplierId: e.target.value })} className="mt-1.5 h-10 w-full rounded-lg border bg-background px-3 text-sm" data-testid="select-purchase-supplier"><option value="">Choose supplier</option>{suppliers.data?.map((supplier) => <option key={supplier.id} value={supplier.id}>{supplier.companyName}</option>)}</select></label><Field label="Invoice number" required value={form.invoiceNumber} onChange={(v) => setForm({ ...form, invoiceNumber: v })} /><label className="block text-sm font-medium">Purchase date<input required type="date" value={form.purchaseDate} onChange={(e) => setForm({ ...form, purchaseDate: e.target.value })} className="mt-1.5 h-10 w-full rounded-lg border bg-background px-3 text-sm" data-testid="input-purchase-date" /></label></div><div className="border-t pt-5"><h2 className="mb-4 font-semibold">First batch</h2><div className="grid gap-4 md:grid-cols-3"><label className="block text-sm font-medium md:col-span-2">Medicine<select required value={form.medicineId} onChange={(e) => setForm({ ...form, medicineId: e.target.value })} className="mt-1.5 h-10 w-full rounded-lg border bg-background px-3 text-sm" data-testid="select-purchase-medicine"><option value="">Choose medicine</option>{medicines.data?.items?.map((medicine) => <option key={medicine.id} value={medicine.id}>{medicine.name} {medicine.strength}</option>)}</select></label><Field label="Batch number" required value={form.batchNumber} onChange={(v) => setForm({ ...form, batchNumber: v })} /><Field label="Manufacturing date" type="date" required value={form.manufacturingDate} onChange={(v) => setForm({ ...form, manufacturingDate: v })} /><Field label="Expiry date" type="date" required value={form.expiryDate} onChange={(v) => setForm({ ...form, expiryDate: v })} /><Field label="Quantity" type="number" required value={form.quantity} onChange={(v) => setForm({ ...form, quantity: v })} /><Field label="Purchase price" type="number" required value={form.purchasePrice} onChange={(v) => setForm({ ...form, purchasePrice: v })} /><Field label="Selling price" type="number" required value={form.sellingPrice} onChange={(v) => setForm({ ...form, sellingPrice: v })} /><Field label="MRP" type="number" required value={form.mrp} onChange={(v) => setForm({ ...form, mrp: v })} /><Field label="GST %" type="number" value={form.gstPercent} onChange={(v) => setForm({ ...form, gstPercent: v })} /></div></div><div className="flex justify-end border-t pt-5"><button disabled={create.isPending} className="rounded-lg bg-primary px-5 py-2.5 text-sm font-semibold text-primary-foreground disabled:opacity-60" data-testid="button-save-purchase">{create.isPending ? 'Saving purchase…' : 'Save purchase and update stock'}</button></div></form></AppShell>;
}

function Reports() {
  const [range, setRange] = useState({ from: '', to: '' });
  const params = useMemo(() => ({ from: range.from || undefined, to: range.to || undefined }), [range]);
  const report = useGetReportSummary(params, { query: { queryKey: getGetReportSummaryQueryKey(params) } });
  const [exportType, setExportType] = useState<ExportReportType>('sales');
  const exporter = useExportReport({ type: exportType, from: range.from || undefined, to: range.to || undefined }, { query: { queryKey: ['/api/reports/export', exportType, range], enabled: false } });
  return <AppShell><PageHeader eyebrow="Insights / Reporting" title="Reports" description="Turn daily operations into decisions with one source of truth." action={<button onClick={() => report.refetch()} className="inline-flex items-center gap-2 rounded-lg border bg-card px-4 py-2.5 text-sm font-semibold hover:bg-muted" data-testid="button-refresh-reports"><RefreshCw size={16} />Refresh</button>} /><div className="card-surface mb-6 flex flex-col gap-3 p-4 md:flex-row md:items-end"><label className="text-xs font-semibold text-muted-foreground">From<input type="date" value={range.from} onChange={(e) => setRange({ ...range, from: e.target.value })} className="mt-1.5 h-9 rounded-lg border bg-background px-2 text-sm" data-testid="input-report-from" /></label><label className="text-xs font-semibold text-muted-foreground">To<input type="date" value={range.to} onChange={(e) => setRange({ ...range, to: e.target.value })} className="mt-1.5 h-9 rounded-lg border bg-background px-2 text-sm" data-testid="input-report-to" /></label><div className="flex-1" /><select value={exportType} onChange={(e) => setExportType(e.target.value as ExportReportType)} className="h-9 rounded-lg border bg-background px-2 text-sm" data-testid="select-export-type"><option value="sales">Sales CSV</option><option value="purchases">Purchases CSV</option><option value="inventory">Inventory CSV</option><option value="expiry">Expiry CSV</option><option value="profit">Profit CSV</option></select><button onClick={() => exporter.refetch()} className="inline-flex h-9 items-center justify-center gap-2 rounded-lg bg-secondary px-3 text-xs font-bold hover:bg-secondary/80" data-testid="button-export-report"><Download size={14} />Export</button></div>{report.isLoading ? <LoadingBlock label="Preparing report summary" /> : report.isError ? <ErrorBlock onRetry={() => report.refetch()} /> : <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Sales revenue" value={money(report.data?.salesRevenue)} detail={`${report.data?.salesCount ?? 0} sales`} icon={TrendingUp} /><MetricCard label="Purchase cost" value={money(report.data?.purchaseCost)} detail={`${report.data?.purchaseCount ?? 0} purchase entries`} tone="blue" icon={ClipboardList} /><MetricCard label="Gross profit" value={money(report.data?.profit)} detail="Revenue less purchase cost" tone="teal" icon={IndianRupee} /><MetricCard label="Expiry exposure" value={money((report.data?.expiredValue ?? 0) + (report.data?.expiringValue ?? 0))} detail={`${money(report.data?.expiredValue)} expired · ${money(report.data?.expiringValue)} expiring`} tone="red" icon={CalendarDays} /></div>}</AppShell>;
}

function SettingsPage() {
  const { data: user } = useGetCurrentUser({ query: { queryKey: ['/api/auth/me'], retry: false } });
  return <AppShell><PageHeader eyebrow="Workspace / Settings" title="Settings" description="Review your pharmacy context and the access identity behind this session." /><div className="grid gap-6 lg:grid-cols-[1.1fr_.9fr]"><section className="card-surface p-6"><div className="mb-6 flex items-center gap-4"><span className="flex h-14 w-14 items-center justify-center rounded-2xl bg-primary/10 text-lg font-bold text-primary">{user?.name?.split(' ').map((part) => part[0]).join('').slice(0, 2) ?? 'PH'}</span><div><h2 className="font-semibold">{user?.name ?? 'Current user'}</h2><p className="text-sm text-muted-foreground">{user?.email ?? 'Account details loading'}</p></div></div><div className="grid gap-4 sm:grid-cols-2"><Info label="Role" value={user?.role ?? '—'} /><Info label="Account ID" value={user?.id ? `USR-${String(user.id).padStart(4, '0')}` : '—'} /><Info label="Workspace" value="Northstar Pharmacy" /><Info label="Session status" value="Active and protected" /></div></section><section className="card-surface p-6"><div className="mb-5 flex items-center gap-3"><span className="rounded-lg bg-emerald-100 p-2 text-emerald-700"><CheckCircle2 size={18} /></span><div><h2 className="font-semibold">Operational defaults</h2><p className="text-xs text-muted-foreground">Managed by your pharmacy administrator.</p></div></div><div className="space-y-3 text-sm"><div className="flex items-center justify-between border-b pb-3"><span className="text-muted-foreground">Currency</span><span className="font-medium">Indian Rupee (₹)</span></div><div className="flex items-center justify-between border-b pb-3"><span className="text-muted-foreground">Expiry monitoring</span><span className="font-medium">Enabled</span></div><div className="flex items-center justify-between"><span className="text-muted-foreground">Inventory alerts</span><span className="font-medium">Live</span></div></div></section></div></AppShell>;
}
function Info({ label, value }: { label: string; value: string }) { return <div className="rounded-lg bg-muted/50 p-3"><span className="block text-[10px] font-bold uppercase tracking-[.1em] text-muted-foreground">{label}</span><strong className="mt-1 block text-sm">{value}</strong></div>; }

export { Dashboard, Login, Medicines, Inventory, SimpleListPage, POS, PurchaseEntry, Reports, SettingsPage, SaleDetails };